#!/usr/bin/env bash
# The evaluation's headline tables, regenerated by one run from one commit, with the code that made them written next to them.
# It refuses to run unless the tool and the Graal fork are exactly a commit and the builder is not older than the fork's sources:
# what provenance.sh records as uncommitted changes, untracked files, a stale builder, or no stamp at all. Run it on pontos04
# (after sync-pontos.sh from a clean checkout), alone: the timed stages wait for a quiet machine.
#
#   graal-native/reproduce.sh --list                  # the stages
#   graal-native/reproduce.sh                         # the default stages (about 2 hours)
#   graal-native/reproduce.sh loads time              # chosen stages
#   graal-native/reproduce.sh all                     # every stage, the long ones too (many hours)
#   graal-native/reproduce.sh --check provenance.txt  # only the decision: is this code a commit? (exit status 1 if it is not)
#   ALLOW_DIRTY=1 graal-native/reproduce.sh shapes    # for testing the script: the results are marked NOT-REPRODUCIBLE
#
# The results are in out/reproduction/<UTC time>-<tool commit>/: provenance.txt (which code), one <stage>.txt for each stage
# (the commands' tables, as printed), and SUMMARY.txt (the stages, their status and time). The builds themselves stay in out/.
describe() {
    cat <<'EOF'
loads       loads left by Graal in the designed programs and in AWFY at -O2: graal, kills, objects (evaluation §3)
time        AWFY at -O3: graal and kills built 4 times, timed together with an A/A pair; loads left per build (§3, §4, F73)
ceiling     AWFY at -O3 with the ceiling: loads left and run times with an A/A pair (§3.1)
cost        build time, our steps, peak RSS of AWFY in every configuration, 5 rounds (§7)
shapes      lock and volatile shapes: Graal's image against the one that removes what thread escape proves (§8.5)
matrix      (long) thread escape on the concurrency examples, every analysis and set of assumptions (§8.3)
javac       (long) javac: cost of kills, the cutoff and lock removal, 3 rounds, and the time it takes to compile (§7, §8.4.2)
frameworks  (long) PetClinic and three Barista servers: builds, removable sites, PetClinic under load (§8.6, §8.7);
            needs ~/eval/petclinic and ~/eval/barista (bundles copied from the laptop)
EOF
}

# Whether the code in a provenance.txt is exactly a commit: no changed tracked files, no untracked ones, no warning that the
# builder is older than the sources, and a stamp for both trees.
refusal() {  # provenance.txt
    local reasons
    reasons=$(grep -E 'uncommitted: [1-9]|, [1-9][0-9]* untracked|WARNING|no history and no stamp' "$1" || true)
    [[ -z $reasons ]] && return 0
    echo "refusing to run: the code is not exactly a commit, or the builder is not made from it:"
    sed 's/^/    /' <<< "$reasons"
    return 1
}

# these two need nothing built: they come before env.sh, which wants the GraalVM
case ${1:-} in
    --list) describe; exit 0 ;;
    --check) refusal "${2:?usage: reproduce.sh --check <provenance.txt>}"; exit $? ;;
esac

source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/env.sh"
source "$HERE/provenance.sh"
export PATH="$GRAALVM/bin:$PATH"  # programs/*/build.sh compile with the javac on the path

DEFAULT_STAGES=(loads time ceiling cost shapes)
ALL_STAGES=(loads time ceiling cost shapes matrix javac frameworks)

wait_quiet() {  # the timings are of a machine with nothing else running
    while [[ $(cut -d. -f1 /proc/loadavg) -ge 2 ]]; do sleep 15; done
    echo "machine quiet at $(date +%T), load $(cut -d' ' -f1-3 /proc/loadavg)"
}

counts() { uv run --project "$REPO" python "$HERE/counts.py" "$@"; }

stage_loads() {
    local p
    for p in Examples Signatures Aliasing Allocation Awfy; do
        local tag=repro; [[ $p == Awfy ]] && tag=repro-o2
        ONLY="graal kills" TAG=$tag "$HERE/run.sh" "$p"
        ALLOCSENS=1 ONLY="graal kills objects" TAG=$tag "$HERE/run.sh" "$p"
    done
    for p in examples signatures aliasing allocation awfy; do
        local tag=repro; [[ $p == awfy ]] && tag=repro-o2
        echo "== $p, default analysis"; counts "$HERE/out/$p-$tag"/{graal,kills}/counts.txt
        echo "== $p, allocation sites"; counts "$HERE/out/$p-allocsens-$tag"/{graal,kills,objects}/counts.txt
    done
}

stage_time() {
    "$HERE/awfy-repeat.sh" 4 5
}

stage_ceiling() {
    ONLY="graal kills ceiling" TAG=repro-ceil EXTRA="-O3 -H:+AOTTrivialInline" "$HERE/run.sh" Awfy
    local o="$HERE/out/awfy-repro-ceil"
    echo "== loads left"; counts "$o"/{graal,kills,ceiling}/counts.txt
    grep "left out" "$o/ceiling/timings.txt"
    wait_quiet
    echo "== run time (the first image twice is the noise)"
    taskset -c 4-7 uv run --project "$REPO" python "$REPO/programs/awfy/time.py" --image "graal=$o/graal/awfy-repro-ceil" \
        --image "graal-again=$o/graal/awfy-repro-ceil" --image "kills=$o/kills/awfy-repro-ceil" --image "ceiling=$o/ceiling/awfy-repro-ceil"
}

stage_cost() {
    REPEATS=${COST_REPEATS:-5} "$HERE/cost.sh" Awfy  # COST_REPEATS=1 to test the stage
    uv run --project "$REPO" python "$HERE/cost.py" "$HERE/out" awfy
}

stage_shapes() {
    wait_quiet
    "$HERE/time_locks.sh" LockShapes
    "$HERE/time_locks.sh" VolatileShapes
}

stage_matrix() {
    "$HERE/thread-escape.sh"
}

stage_javac() {
    local o="$HERE/out"
    REPEATS=3 CONFIGS="graal kills" "$HERE/cost-javac.sh"
    uv run --project "$REPO" python "$HERE/cost.py" "$o" javac
    REPEATS=3 CONFIGS="graal-allocsens graalcutoff-allocsens graalflagscutoff-allocsens lockscutoff" "$HERE/cost-javac.sh"
    uv run --project "$REPO" python "$HERE/cost.py" "$o" javac-allocsens
    local r
    echo "== the locks the builds removed"
    for r in 1 2 3; do echo "round $r: $(grep -h 'locks removed' "$o/javac-allocsens-cost-lockscutoff-r$r/locks/timings.txt")"; done
    echo "== loads left in javac's own classes"
    counts "$o/javac-allocsens-cost-graal-r1/graal/counts.txt" "$o/javac-allocsens-cost-graalcutoff-r1/graal/counts.txt" \
        "$o/javac-allocsens-cost-graalflagscutoff-r1/graal/counts.txt" "$o/javac-allocsens-cost-lockscutoff-r1/locks/counts.txt"
    rm -rf "$o/javac-aa-copy" && mkdir -p "$o/javac-aa-copy/graal" && cp "$o/javac-allocsens-cost-graal-r1/graal/javac" "$o/javac-aa-copy/graal/javac"
    wait_quiet
    echo "== time javac takes to compile AWFY's sources (the second image is an A/A copy of the first)"
    taskset -c 4-7 uv run --project "$REPO" python "$HERE/time_javac.py" "$o/javac-allocsens-cost-graal-r1" "$o/javac-aa-copy" \
        "$o/javac-allocsens-cost-graalcutoff-r1" "$o"/javac-allocsens-cost-graalflagscutoff-r{1,2,3} "$o"/javac-allocsens-cost-lockscutoff-r{1,2,3} --runs 10
}

stage_frameworks() {
    local app r
    "$HERE/petclinic.sh" graal kills graalflagscutoff lockscutoff
    for app in vanilla-hello-world vertx-hello-world micronaut-hello-world; do
        "$HERE/barista.sh" "$app" graal kills locks lockscutoff
    done
    for r in "$HERE/out/petclinic/lockscutoff" "$HERE"/out/barista/*/locks "$HERE"/out/barista/*/lockscutoff; do
        echo "== why no lock is removable in $r"
        uv run --project "$REPO" python "$HERE/why_no_locks.py" "$r/locks/export.json"
    done
    wait_quiet
    local p="$HERE/out/petclinic"
    python3 "$HERE/petclinic_load.py" --image graal-1="$p/graal/image" --image graal-1-again="$p/graal/image" --image kills="$p/kills/image" \
        --image flags="$p/graalflagscutoff/image" --image locks="$p/lockscutoff/image" --runs 5 --seconds 30 --warmup 15 --clients 16
}

main() {
    if [[ ${1:-} == --run ]]; then  # one stage, run by the script itself so that set -e holds in it
        "stage_${2:?}"
        return $?
    fi
    local stages=("$@") stage
    [[ ${#stages[@]} -gt 0 ]] || stages=("${DEFAULT_STAGES[@]}")
    [[ ${stages[0]} != all ]] || stages=("${ALL_STAGES[@]}")
    for stage in "${stages[@]}"; do
        declare -F "stage_$stage" > /dev/null || { echo "unknown stage $stage (see --list)" >&2; return 2; }
    done

    local commit
    commit=$(sed -n 's/^commit: \([0-9a-f]\{7\}\).*/\1/p' "$REPO/.synced-from" 2> /dev/null | head -1)
    [[ -n $commit ]] || commit=$(git -C "$REPO" rev-parse --short HEAD 2> /dev/null || echo unknown)
    local results="$HERE/out/reproduction/$(date -u +%Y%m%dT%H%M%SZ)-$commit"
    mkdir -p "$results"
    provenance "$results"
    if ! refusal "$results/provenance.txt"; then
        if [[ ${ALLOW_DIRTY:-} != 1 ]]; then
            rm -rf "$results"
            return 1
        fi
        echo "ALLOW_DIRTY=1: going on, and these results are marked NOT-REPRODUCIBLE"
        echo "the code was not exactly a commit (ALLOW_DIRTY=1); see provenance.txt" > "$results/NOT-REPRODUCIBLE"
    fi
    echo "results in $results"

    local failed=() start status
    {
        echo "stage        status   seconds"
        for stage in "${stages[@]}"; do
            echo "== $stage ($(date +%T))" >&2
            start=$SECONDS
            status=ok
            set +e
            bash "${BASH_SOURCE[0]}" --run "$stage" 2>&1 | tee "$results/$stage.txt" >&2
            [[ ${PIPESTATUS[0]} -eq 0 ]] || status=FAILED
            set -e
            [[ $status == ok ]] || failed+=("$stage")
            printf '%-12s %-8s %s\n' "$stage" "$status" "$((SECONDS - start))"
        done
    } | tee "$results/SUMMARY.txt"
    [[ ${#failed[@]} -eq 0 ]] || { echo "failed: ${failed[*]}" >&2; return 1; }
}

main "$@"
